    int crew, days;
    double grams;
    // read all three, then print the total in kg
    return 0;
}

solution:
#include <stdio.h>

int main(void) {
    int crew, days;
    double grams;
    scanf("%d %d %lf", &crew, &days, &grams);
    double kilograms = crew * days * grams / 1000;
    printf("Rations: %.1f kg\n", kilograms);
    return 0;
}
